class OutsetsF : public InsetsOutsetsFBase<OutsetsF> {
 public:
  using InsetsOutsetsFBase::InsetsOutsetsFBase;


  InsetsF ToInsets() const {
    return InsetsF()
        .set_left(-left())
        .set_right(-right())
        .set_top(-top())
        .set_bottom(-bottom());
  }
};

inline OutsetsF operator+(OutsetsF lhs, const OutsetsF& rhs) {
  lhs += rhs;
  return lhs;
}

inline OutsetsF operator-(OutsetsF lhs, const OutsetsF& rhs) {
  lhs -= rhs;
  return lhs;
}




